const STAGES = [
  { key: "pending", label: "待投递" },
  { key: "applied", label: "已投递" },
  { key: "interview", label: "面试中" },
  { key: "closed", label: "已结束" }
];
const STAGE_LABELS = STAGES.reduce(function (acc, s) { acc[s.key] = s.label; return acc; }, {});
const STAGE_KEYS = STAGES.map(function (s) { return s.key; });

const root = app;

const els = {
  statsList: root.querySelector("[data-stats-list]"),
  totalCount: root.querySelector("[data-total-count]"),
  form: root.querySelector("[data-record-form]"),
  formTitle: root.querySelector("[data-form-title]"),
  company: root.querySelector("#field-company"),
  position: root.querySelector("#field-position"),
  appliedAt: root.querySelector("#field-date"),
  stage: root.querySelector("#field-stage"),
  note: root.querySelector("#field-note"),
  formError: root.querySelector("[data-form-error]"),
  submitBtn: root.querySelector("[data-submit-btn]"),
  cancelEdit: root.querySelector("[data-cancel-edit]"),
  searchInput: root.querySelector("[data-search-input]"),
  searchClear: root.querySelector("[data-search-clear]"),
  listCount: root.querySelector("[data-list-count]"),
  recordList: root.querySelector("[data-record-list]"),
  emptyHint: root.querySelector("[data-empty-hint]"),
  filterButtons: Array.prototype.slice.call(root.querySelectorAll("[data-filter]")),
  dialog: root.querySelector("[data-dialog]"),
  dialogTitle: root.querySelector("[data-dialog-title]"),
  dialogText: root.querySelector("[data-dialog-text]"),
  dialogCancel: root.querySelector("[data-dialog-cancel]"),
  dialogConfirm: root.querySelector("[data-dialog-confirm]")
};

let state = null;
let editingId = null;
let activeFilter = "all";
let searchTerm = "";

function normalizeStage(value) {
  return STAGE_KEYS.indexOf(value) >= 0 ? value : "pending";
}

function normalizeRecord(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const rec = Object.assign({}, src);
  rec.id = typeof src.id === "string" && src.id ? src.id : createId();
  rec.company = typeof src.company === "string" ? src.company : "";
  rec.position = typeof src.position === "string" ? src.position : "";
  rec.appliedAt = typeof src.appliedAt === "string" ? src.appliedAt : "";
  rec.stage = normalizeStage(src.stage);
  rec.note = typeof src.note === "string" ? src.note : "";
  return rec;
}

function createId() {
  return "rec-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
}

function getRecords() {
  return Array.isArray(state.records) ? state.records : [];
}

function todayISO() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return d.getFullYear() + "-" + m + "-" + day;
}

function formatDate(value) {
  if (!value) return "未填写日期";
  const parts = String(value).split("-");
  if (parts.length !== 3) return String(value);
  return parts[0] + " 年 " + Number(parts[1]) + " 月 " + Number(parts[2]) + " 日";
}

function showError(message) {
  if (!message) {
    els.formError.hidden = true;
    els.formError.textContent = "";
    return;
  }
  els.formError.textContent = message;
  els.formError.hidden = false;
}

function matchesSearch(rec) {
  if (!searchTerm) return true;
  const company = String(rec.company || "").toLowerCase();
  return company.indexOf(searchTerm) >= 0;
}

function getVisibleRecords() {
  const records = getRecords();
  return records.filter(function (rec) {
    if (activeFilter !== "all" && normalizeStage(rec.stage) !== activeFilter) return false;
    return matchesSearch(rec);
  });
}

function renderStats() {
  const records = getRecords();
  const counts = STAGE_KEYS.reduce(function (acc, key) { acc[key] = 0; return acc; }, {});
  records.forEach(function (rec) {
    const key = normalizeStage(rec.stage);
    counts[key] += 1;
  });

  els.statsList.textContent = "";
  STAGES.forEach(function (stage) {
    const li = document.createElement("li");
    li.className = "stat-item";

    const nameWrap = document.createElement("span");
    nameWrap.className = "stat-name";
    const dot = document.createElement("span");
    dot.className = "stat-dot";
    dot.setAttribute("data-stage", stage.key);
    const nameText = document.createElement("span");
    nameText.textContent = stage.label;
    nameWrap.appendChild(dot);
    nameWrap.appendChild(nameText);

    const value = document.createElement("span");
    value.className = "stat-value";
    value.textContent = String(counts[stage.key]);

    li.appendChild(nameWrap);
    li.appendChild(value);
    els.statsList.appendChild(li);
  });

  const total = STAGE_KEYS.reduce(function (sum, key) { return sum + counts[key]; }, 0);
  els.totalCount.textContent = String(total);
}

function renderFilters() {
  els.filterButtons.forEach(function (btn) {
    const key = btn.getAttribute("data-filter");
    if (key === activeFilter) {
      btn.classList.add("is-active");
    } else {
      btn.classList.remove("is-active");
    }
  });
}

function renderSearch() {
  if (els.searchInput.value !== searchTerm) {
    els.searchInput.value = searchTerm;
  }
  els.searchClear.hidden = searchTerm.length === 0;
}

function renderList() {
  const records = getRecords();
  const visible = getVisibleRecords();

  els.recordList.textContent = "";

  visible.forEach(function (rec) {
    const li = document.createElement("li");
    li.className = "record-card";
    li.setAttribute("data-stage", normalizeStage(rec.stage));

    const top = document.createElement("div");
    top.className = "record-top";

    const titleWrap = document.createElement("div");
    const company = document.createElement("h3");
    company.className = "record-company";
    company.textContent = rec.company || "未填写公司";
    const position = document.createElement("p");
    position.className = "record-position";
    position.textContent = rec.position || "未填写岗位";
    titleWrap.appendChild(company);
    titleWrap.appendChild(position);

    const badge = document.createElement("span");
    badge.className = "stage-badge";
    badge.setAttribute("data-stage", normalizeStage(rec.stage));
    badge.textContent = STAGE_LABELS[normalizeStage(rec.stage)];

    top.appendChild(titleWrap);
    top.appendChild(badge);

    const meta = document.createElement("p");
    meta.className = "record-meta";
    meta.textContent = "投递日期：" + formatDate(rec.appliedAt);

    li.appendChild(top);
    li.appendChild(meta);

    if (rec.note) {
      const note = document.createElement("p");
      note.className = "record-note";
      note.textContent = rec.note;
      li.appendChild(note);
    }

    const actions = document.createElement("div");
    actions.className = "record-actions";

    const editBtn = document.createElement("button");
    editBtn.type = "button";
    editBtn.className = "btn btn-ghost";
    editBtn.textContent = "编辑";
    editBtn.addEventListener("click", function () {
      startEdit(rec.id);
    });

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "btn btn-ghost";
    delBtn.textContent = "删除";
    delBtn.addEventListener("click", function () {
      askDelete(rec.id);
    });

    actions.appendChild(editBtn);
    actions.appendChild(delBtn);
    li.appendChild(actions);

    els.recordList.appendChild(li);
  });

  const total = records.length;
  const parts = [];
  if (activeFilter === "all") {
    parts.push("共 " + total + " 条");
  } else {
    parts.push("阶段「" + STAGE_LABELS[activeFilter] + "」" + visible.length + " 条");
  }
  if (searchTerm) {
    parts.push("搜索命中 " + visible.length + " 条");
  }
  if (activeFilter !== "all" || searchTerm) {
    parts.push("全部 " + total + " 条");
  }
  els.listCount.textContent = parts.join(" · ");

  if (visible.length === 0) {
    els.emptyHint.hidden = false;
    if (total === 0) {
      els.emptyHint.textContent = "还没有投递记录，先在上方新增一条吧。";
    } else if (searchTerm && activeFilter !== "all") {
      els.emptyHint.textContent = "没有同时符合当前阶段与搜索关键字的记录，试试调整条件。";
    } else if (searchTerm) {
      els.emptyHint.textContent = "没有公司名称包含「" + searchTerm + "」的记录。";
    } else {
      els.emptyHint.textContent = "当前阶段下没有记录，试试切换筛选条件。";
    }
  } else {
    els.emptyHint.hidden = true;
    els.emptyHint.textContent = "";
  }
}

function renderAll() {
  renderStats();
  renderFilters();
  renderSearch();
  renderList();
}

function resetForm() {
  editingId = null;
  els.form.reset();
  els.appliedAt.value = todayISO();
  els.stage.value = "pending";
  els.formTitle.textContent = "新增投递记录";
  els.submitBtn.textContent = "保存记录";
  els.cancelEdit.hidden = true;
  showError("");
}

function startEdit(id) {
  const rec = getRecords().filter(function (r) { return r.id === id; })[0];
  if (!rec) return;
  editingId = id;
  els.company.value = rec.company || "";
  els.position.value = rec.position || "";
  els.appliedAt.value = rec.appliedAt || "";
  els.stage.value = normalizeStage(rec.stage);
  els.note.value = rec.note || "";
  els.formTitle.textContent = "编辑投递记录";
  els.submitBtn.textContent = "保存修改";
  els.cancelEdit.hidden = false;
  showError("");
  if (typeof els.company.focus === "function") {
    els.company.focus();
  }
}

async function persist(nextRecords) {
  const next = Object.assign({}, state);
  next.records = nextRecords;
  await appStore.setState(next);
  state = await appStore.getState();
  if (!Array.isArray(state.records)) {
    state = Object.assign({}, state, { records: [] });
  }
}

async function handleSubmit(event) {
  event.preventDefault();
  const company = els.company.value.trim();
  const position = els.position.value.trim();
  const appliedAt = els.appliedAt.value;
  const stage = normalizeStage(els.stage.value);
  const note = els.note.value.trim();

  if (!company) {
    showError("请填写公司名称。");
    return;
  }
  if (!position) {
    showError("请填写应聘岗位。");
    return;
  }
  showError("");

  const records = getRecords().slice();
  const targetId = editingId;

  if (targetId) {
    const index = records.findIndex(function (r) { return r.id === targetId; });
    if (index < 0) {
      showError("未找到要编辑的记录，请刷新后重试。");
      return;
    }
    records[index] = Object.assign({}, records[index], {
      company: company,
      position: position,
      appliedAt: appliedAt,
      stage: stage,
      note: note
    });
  } else {
    records.push({
      id: createId(),
      company: company,
      position: position,
      appliedAt: appliedAt,
      stage: stage,
      note: note
    });
  }

  try {
    await persist(records);
  } catch (err) {
    showError("保存失败，请重试。你的输入已保留。");
    return;
  }

  resetForm();
  renderAll();
}

function askDelete(id) {
  const rec = getRecords().filter(function (r) { return r.id === id; })[0];
  if (!rec) return;
  const label = (rec.company || "未填写公司") + " · " + (rec.position || "未填写岗位");
  openDialog("确认删除", "确定要删除「" + label + "」这条投递记录吗？删除后无法恢复。", "确认删除", async function () {
    const records = getRecords().filter(function (r) { return r.id !== id; });
    try {
      await persist(records);
    } catch (err) {
      showError("删除失败，请重试。");
      return;
    }
    if (editingId === id) {
      resetForm();
    }
    renderAll();
  });
}

let dialogHandler = null;

function openDialog(title, text, confirmLabel, onConfirm) {
  els.dialogTitle.textContent = title;
  els.dialogText.textContent = text;
  els.dialogConfirm.textContent = confirmLabel;
  dialogHandler = onConfirm;
  els.dialog.hidden = false;
  if (typeof els.dialogConfirm.focus === "function") {
    els.dialogConfirm.focus();
  }
}

function closeDialog() {
  els.dialog.hidden = true;
  dialogHandler = null;
}

async function init() {
  const raw = await appStore.getState();
  const base = raw && typeof raw === "object" ? raw : {};
  const hasRecords = Array.isArray(base.records);
  state = Object.assign({}, base);
  state.records = hasRecords ? base.records.map(normalizeRecord) : [];

  if (!hasRecords) {
    try {
      await persist(state.records);
    } catch (err) {
      state = Object.assign({}, base, { records: [] });
    }
  }

  els.form.addEventListener("submit", handleSubmit);

  els.cancelEdit.addEventListener("click", function () {
    resetForm();
  });

  els.searchInput.addEventListener("input", function () {
    searchTerm = els.searchInput.value.trim().toLowerCase();
    renderSearch();
    renderList();
  });

  els.searchClear.addEventListener("click", function () {
    searchTerm = "";
    renderSearch();
    renderList();
    if (typeof els.searchInput.focus === "function") {
      els.searchInput.focus();
    }
  });

  els.filterButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      activeFilter = btn.getAttribute("data-filter") || "all";
      renderFilters();
      renderList();
    });
  });

  els.dialogCancel.addEventListener("click", function () {
    closeDialog();
  });

  els.dialogConfirm.addEventListener("click", async function () {
    const handler = dialogHandler;
    closeDialog();
    if (typeof handler === "function") {
      await handler();
    }
  });

  els.dialog.addEventListener("click", function (event) {
    if (event.target === els.dialog) {
      closeDialog();
    }
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !els.dialog.hidden) {
      closeDialog();
    }
  });

  resetForm();
  renderAll();
}

await init();

artifact.css:
:root {
  --bg-900: #0a1220;
  --bg-800: #0f1b2d;
  --bg-700: #142338;
  --bg-600: #1b2f4a;
  --line: #24395a;
  --line-soft: #1d2f4b;
  --accent: #4c9bf5;
  --accent-strong: #2f7fe0;
  --accent-soft: rgba(76, 155, 245, 0.16);
  --text: #e8f1fb;
  --text-soft: #9db4cf;
  --text-dim: #7d93ae;
  --danger: #ff6b7a;
  --danger-soft: rgba(255, 107, 122, 0.14);
  --shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
  --radius: 14px;
}

#app {
  min-height: 100vh;
  background: radial-gradient(120% 90% at 50% 0%, #16273f 0%, var(--bg-900) 55%, #070d17 100%);
  color: var(--text);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-header {
  padding: 18px 18px 20px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, #1d3a63 0%, #14263f 100%);
  border: 1px solid var(--line);
  color: var(--text);
  box-shadow: var(--shadow);
}

.app-title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #ffffff;
}

.app-subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--text-soft);
}

.stats {
  background: var(--bg-800);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px;
  box-shadow: var(--shadow);
}

.stats-total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 4px 6px 12px;
  border-bottom: 1px dashed var(--line);
}

.stats-total-label {
  font-size: 14px;
  color: var(--text-soft);
}

.stats-total-value {
  font-size: 26px;
  font-weight: 700;
  color: var(--accent);
}

.stats-list {
  list-style: none;
  margin: 12px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.stat-item {
  background: var(--bg-700);
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.stat-name {
  font-size: 13px;
  color: var(--text-soft);
  display: flex;
  align-items: center;
  gap: 6px;
}

.stat-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--accent);
  flex: none;
}

.stat-dot[data-stage="pending"] { background: #8fa6c4; }
.stat-dot[data-stage="applied"] { background: var(--accent); }
.stat-dot[data-stage="interview"] { background: #f2b13c; }
.stat-dot[data-stage="closed"] { background: #6c7d92; }

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
}

.panel {
  background: var(--bg-800);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
}

.panel-title {
  margin: 0 0 12px;
  font-size: 16px;
  font-weight: 700;
  color: var(--text);
}

.record-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field-full {
  grid-column: 1 / -1;
}

.field-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-soft);
}

.field-input {
  width: 100%;
  padding: 10px 12px;
  font-size: 15px;
  font-family: inherit;
  color: var(--text);
  background: var(--bg-700);
  border: 1px solid var(--line);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
  appearance: none;
}

.field-input::placeholder {
  color: var(--text-dim);
}

.field-input:focus {
  background: var(--bg-600);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.field-textarea {
  resize: vertical;
  min-height: 72px;
}

select.field-input {
  background-image: linear-gradient(45deg, transparent 50%, var(--accent) 50%), linear-gradient(135deg, var(--accent) 50%, transparent 50%);
  background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

select.field-input option {
  background: var(--bg-700);
  color: var(--text);
}

input[type="date"].field-input::-webkit-calendar-picker-indicator {
  filter: invert(0.8);
  cursor: pointer;
}

.form-error {
  grid-column: 1 / -1;
  margin: 0;
  padding: 8px 12px;
  border-radius: 10px;
  background: var(--danger-soft);
  color: var(--danger);
  font-size: 13px;
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  padding: 10px 18px;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.1s ease, background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--accent-strong);
  color: #ffffff;
  flex: 1 1 160px;
}

.btn-primary:hover {
  background: var(--accent);
}

.btn-ghost {
  background: var(--bg-700);
  color: var(--text);
  border-color: var(--line);
}

.btn-ghost:hover {
  background: var(--bg-600);
  border-color: var(--accent);
}

.btn-danger {
  background: #d63a4c;
  color: #ffffff;
}

.btn-danger:hover {
  background: #e8495c;
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.list-count {
  font-size: 13px;
  color: var(--text-soft);
}

.search-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 4px 0 12px;
}

.search-label {
  display: block;
}

.search-box {
  display: flex;
  gap: 8px;
  align-items: stretch;
}

.search-input {
  flex: 1 1 auto;
  min-width: 0;
}

.search-clear {
  flex: none;
  font-size: 13px;
  padding: 8px 14px;
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 0 14px;
}

.chip {
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  padding: 7px 14px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--bg-700);
  color: var(--text-soft);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.chip:hover {
  background: var(--bg-600);
  color: var(--text);
}

.chip.is-active {
  background: var(--accent-strong);
  border-color: var(--accent);
  color: #ffffff;
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.record-card {
  border: 1px solid var(--line-soft);
  border-left: 4px solid var(--accent);
  border-radius: 12px;
  background: var(--bg-700);
  padding: 12px 14px;
}

.record-card[data-stage="pending"] { border-left-color: #8fa6c4; }
.record-card[data-stage="applied"] { border-left-color: var(--accent); }
.record-card[data-stage="interview"] { border-left-color: #f2b13c; }
.record-card[data-stage="closed"] { border-left-color: #6c7d92; }

.record-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--text);
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--text-soft);
  word-break: break-word;
}

.stage-badge {
  flex: none;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
  white-space: nowrap;
}

.stage-badge[data-stage="pending"] { background: rgba(143, 166, 196, 0.18); color: #b6c8dd; }
.stage-badge[data-stage="applied"] { background: rgba(76, 155, 245, 0.18); color: #7fbcfb; }
.stage-badge[data-stage="interview"] { background: rgba(242, 177, 60, 0.18); color: #f5c46b; }
.stage-badge[data-stage="closed"] { background: rgba(108, 125, 146, 0.2); color: #a6b4c4; }

.record-meta {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--text-soft);
}

.record-note {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--text);
  background: var(--bg-800);
  border: 1px dashed var(--line);
  border-radius: 10px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.record-actions .btn {
  font-size: 13px;
  padding: 7px 14px;
}

.empty-hint {
  margin: 8px 0 0;
  padding: 22px 12px;
  text-align: center;
  font-size: 14px;
  color: var(--text-soft);
  background: var(--bg-700);
  border: 1px dashed var(--line);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 9, 17, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 340px;
  background: var(--bg-800);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.6);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  color: var(--text);
}

.dialog-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--text-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

@media (max-width: 520px) {
  .app-shell {
    padding: 14px 12px 40px;
  }

  .record-form {
    grid-template-columns: minmax(0, 1fr);
  }

  .stats-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .app-title {
    font-size: 20px;
  }
}

artifact.js:
const STAGES = [
  { key: "pending", label: "待投递" },
  { key: "applied", label: "已投递" },
  { key: "interview", label: "面试中" },
  { key: "closed", label: "已结束" }
];
const STAGE_LABELS = STAGES.reduce(function (acc, s) { acc[s.key] = s.label; return acc; }, {});
const STAGE_KEYS = STAGES.map(function (s) { return s.key; });

const SORT_ORDERS = ["desc", "asc"];
const SORT_LABELS = { desc: "日期降序", asc: "日期升序" };

const root = app;

const els = {
  statsList: root.querySelector("[data-stats-list]"),
  totalCount: root.querySelector("[data-total-count]"),
  form: root.querySelector("[data-record-form]"),
  formTitle: root.querySelector("[data-form-title]"),
  company: root.querySelector("#field-company"),
  position: root.querySelector("#field-position"),
  appliedAt: root.querySelector("#field-date"),
  stage: root.querySelector("#field-stage"),
  note: root.querySelector("#field-note"),
  formError: root.querySelector("[data-form-error]"),
  submitBtn: root.querySelector("[data-submit-btn]"),
  cancelEdit: root.querySelector("[data-cancel-edit]"),
  searchInput: root.querySelector("[data-search-input]"),
  searchClear: root.querySelector("[data-search-clear]"),
  listCount: root.querySelector("[data-list-count]"),
  recordList: root.querySelector("[data-record-list]"),
  emptyHint: root.querySelector("[data-empty-hint]"),
  filterButtons: Array.prototype.slice.call(root.querySelectorAll("[data-filter]")),
  sortButtons: Array.prototype.slice.call(root.querySelectorAll("[data-sort]")),
  dialog: root.querySelector("[data-dialog]"),
  dialogTitle: root.querySelector("[data-dialog-title]"),
  dialogText: root.querySelector("[data-dialog-text]"),
  dialogCancel: root.querySelector("[data-dialog-cancel]"),
  dialogConfirm: root.querySelector("[data-dialog-confirm]")
};

let state = null;
let editingId = null;
let activeFilter = "all";
let searchTerm = "";
let sortOrder = "desc";

function normalizeStage(value) {
  return STAGE_KEYS.indexOf(value) >= 0 ? value : "pending";
}

function normalizeSortOrder(value) {
  return SORT_ORDERS.indexOf(value) >= 0 ? value : "desc";
}

function normalizeRecord(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const rec = Object.assign({}, src);
  rec.id = typeof src.id === "string" && src.id ? src.id : createId();
  rec.company = typeof src.company === "string" ? src.company : "";
  rec.position = typeof src.position === "string" ? src.position : "";
  rec.appliedAt = typeof src.appliedAt === "string" ? src.appliedAt : "";
  rec.stage = normalizeStage(src.stage);
  rec.note = typeof src.note === "string" ? src.note : "";
  return rec;
}

function createId() {
  return "rec-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
}

function getRecords() {
  return Array.isArray(state.records) ? state.records : [];
}

function todayISO() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return d.getFullYear() + "-" + m + "-" + day;
}

function formatDate(value) {
  if (!value) return "未填写日期";
  const parts = String(value).split("-");
  if (parts.length !== 3) return String(value);
  return parts[0] + " 年 " + Number(parts[1]) + " 月 " + Number(parts[2]) + " 日";
}

function showError(message) {
  if (!message) {
    els.formError.hidden = true;
    els.formError.textContent = "";
    return;
  }
  els.formError.textContent = message;
  els.formError.hidden = false;
}

function matchesSearch(rec) {
  if (!searchTerm) return true;
  const company = String(rec.company || "").toLowerCase();
  return company.indexOf(searchTerm) >= 0;
}

function sortRecords(records) {
  const dir = sortOrder === "asc" ? 1 : -1;
  return records.slice().sort(function (a, b) {
    const da = typeof a.appliedAt === "string" ? a.appliedAt : "";
    const db = typeof b.appliedAt === "string" ? b.appliedAt : "";
    if (!da && !db) return 0;
    if (!da) return 1;
    if (!db) return -1;
    if (da === db) return 0;
    return da < db ? -dir : dir;
  });
}

function getVisibleRecords() {
  const records = getRecords();
  const filtered = records.filter(function (rec) {
    if (activeFilter !== "all" && normalizeStage(rec.stage) !== activeFilter) return false;
    return matchesSearch(rec);
  });
  return sortRecords(filtered);
}

function renderStats() {
  const records = getRecords();
  const counts = STAGE_KEYS.reduce(function (acc, key) { acc[key] = 0; return acc; }, {});
  records.forEach(function (rec) {
    const key = normalizeStage(rec.stage);
    counts[key] += 1;
  });

  els.statsList.textContent = "";
  STAGES.forEach(function (stage) {
    const li = document.createElement("li");
    li.className = "stat-item";

    const nameWrap = document.createElement("span");
    nameWrap.className = "stat-name";
    const dot = document.createElement("span");
    dot.className = "stat-dot";
    dot.setAttribute("data-stage", stage.key);
    const nameText = document.createElement("span");
    nameText.textContent = stage.label;
    nameWrap.appendChild(dot);
    nameWrap.appendChild(nameText);

    const value = document.createElement("span");
    value.className = "stat-value";
    value.textContent = String(counts[stage.key]);

    li.appendChild(nameWrap);
    li.appendChild(value);
    els.statsList.appendChild(li);
  });

  const total = STAGE_KEYS.reduce(function (sum, key) { return sum + counts[key]; }, 0);
  els.totalCount.textContent = String(total);
}

function renderFilters() {
  els.filterButtons.forEach(function (btn) {
    const key = btn.getAttribute("data-filter");
    if (key === activeFilter) {
      btn.classList.add("is-active");
    } else {
      btn.classList.remove("is-active");
    }
  });
}

function renderSort() {
  els.sortButtons.forEach(function (btn) {
    const key = normalizeSortOrder(btn.getAttribute("data-sort"));
    const isActive = key === sortOrder;
    if (isActive) {
      btn.classList.add("is-active");
    } else {
      btn.classList.remove("is-active");
    }
    btn.setAttribute("aria-pressed", isActive ? "true" : "false");
  });
}

function renderSearch() {
  if (els.searchInput.value !== searchTerm) {
    els.searchInput.value = searchTerm;
  }
  els.searchClear.hidden = searchTerm.length === 0;
}

function renderList() {
  const records = getRecords();
  const visible = getVisibleRecords();

  els.recordList.textContent = "";

  visible.forEach(function (rec) {
    const li = document.createElement("li");
    li.className = "record-card";
    li.setAttribute("data-stage", normalizeStage(rec.stage));

    const top = document.createElement("div");
    top.className = "record-top";

    const titleWrap = document.createElement("div");
    const company = document.createElement("h3");
    company.className = "record-company";
    company.textContent = rec.company || "未填写公司";
    const position = document.createElement("p");
    position.className = "record-position";
    position.textContent = rec.position || "未填写岗位";
    titleWrap.appendChild(company);
    titleWrap.appendChild(position);

    const badge = document.createElement("span");
    badge.className = "stage-badge";
    badge.setAttribute("data-stage", normalizeStage(rec.stage));
    badge.textContent = STAGE_LABELS[normalizeStage(rec.stage)];

    top.appendChild(titleWrap);
    top.appendChild(badge);

    const meta = document.createElement("p");
    meta.className = "record-meta";
    meta.textContent = "投递日期：" + formatDate(rec.appliedAt);

    li.appendChild(top);
    li.appendChild(meta);

    if (rec.note) {
      const note = document.createElement("p");
      note.className = "record-note";
      note.textContent = rec.note;
      li.appendChild(note);
    }

    const actions = document.createElement("div");
    actions.className = "record-actions";

    const editBtn = document.createElement("button");
    editBtn.type = "button";
    editBtn.className = "btn btn-ghost";
    editBtn.textContent = "编辑";
    editBtn.addEventListener("click", function () {
      startEdit(rec.id);
    });

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "btn btn-ghost";
    delBtn.textContent = "删除";
    delBtn.addEventListener("click", function () {
      askDelete(rec.id);
    });

    actions.appendChild(editBtn);
    actions.appendChild(delBtn);
    li.appendChild(actions);

    els.recordList.appendChild(li);
  });

  const total = records.length;
  const parts = [];
  if (activeFilter === "all") {
    parts.push("共 " + total + " 条");
  } else {
    parts.push("阶段「" + STAGE_LABELS[activeFilter] + "」" + visible.length + " 条");
  }
  if (searchTerm) {
    parts.push("搜索命中 " + visible.length + " 条");
  }
  if (activeFilter !== "all" || searchTerm) {
    parts.push("全部 " + total + " 条");
  }
  parts.push("排序：" + SORT_LABELS[sortOrder]);
  els.listCount.textContent = parts.join(" · ");

  if (visible.length === 0) {
    els.emptyHint.hidden = false;
    if (total === 0) {
      els.emptyHint.textContent = "还没有投递记录，先在上方新增一条吧。";
    } else if (searchTerm && activeFilter !== "all") {
      els.emptyHint.textContent = "没有同时符合当前阶段与搜索关键字的记录，试试调整条件。";
    } else if (searchTerm) {
      els.emptyHint.textContent = "没有公司名称包含「" + searchTerm + "」的记录。";
    } else {
      els.emptyHint.textContent = "当前阶段下没有记录，试试切换筛选条件。";
    }
  } else {
    els.emptyHint.hidden = true;
    els.emptyHint.textContent = "";
  }
}

function renderAll() {
  renderStats();
  renderFilters();
  renderSort();
  renderSearch();
  renderList();
}

function resetForm() {
  editingId = null;
  els.form.reset();
  els.appliedAt.value = todayISO();
  els.stage.value = "pending";
  els.formTitle.textContent = "新增投递记录";
  els.submitBtn.textContent = "保存记录";
  els.cancelEdit.hidden = true;
  showError("");
}

function startEdit(id) {
  const rec = getRecords().filter(function (r) { return r.id === id; })[0];
  if (!rec) return;
  editingId = id;
  els.company.value = rec.company || "";
  els.position.value = rec.position || "";
  els.appliedAt.value = rec.appliedAt || "";
  els.stage.value = normalizeStage(rec.stage);
  els.note.value = rec.note || "";
  els.formTitle.textContent = "编辑投递记录";
  els.submitBtn.textContent = "保存修改";
  els.cancelEdit.hidden = false;
  showError("");
  if (typeof els.company.focus === "function") {
    els.company.focus();
  }
}

async function persist(nextRecords) {
  const next = Object.assign({}, state);
  next.records = nextRecords;
  await appStore.setState(next);
  state = await appStore.getState();
  if (!Array.isArray(state.records)) {
    state = Object.assign({}, state, { records: [] });
  }
}

async function handleSubmit(event) {
  event.preventDefault();
  const company = els.company.value.trim();
  const position = els.position.value.trim();
  const appliedAt = els.appliedAt.value;
  const stage = normalizeStage(els.stage.value);
  const note = els.note.value.trim();

  if (!company) {
    showError("请填写公司名称。");
    return;
  }
  if (!position) {
    showError("请填写应聘岗位。");
    return;
  }
  showError("");

  const records = getRecords().slice();
  const targetId = editingId;

  if (targetId) {
    const index = records.findIndex(function (r) { return r.id === targetId; });
    if (index < 0) {
      showError("未找到要编辑的记录，请刷新后重试。");
      return;
    }
    records[index] = Object.assign({}, records[index], {
      company: company,
      position: position,
      appliedAt: appliedAt,
      stage: stage,
      note: note
    });
  } else {
    records.push({
      id: createId(),
      company: company,
      position: position,
      appliedAt: appliedAt,
      stage: stage,
      note: note
    });
  }

  try {
    await persist(records);
  } catch (err) {
    showError("保存失败，请重试。你的输入已保留。");
    return;
  }

  resetForm();
  renderAll();
}

function askDelete(id) {
  const rec = getRecords().filter(function (r) { return r.id === id; })[0];
  if (!rec) return;
  const label = (rec.company || "未填写公司") + " · " + (rec.position || "未填写岗位");
  openDialog("确认删除", "确定要删除「" + label + "」这条投递记录吗？删除后无法恢复。", "确认删除", async function () {
    const records = getRecords().filter(function (r) { return r.id !== id; });
    try {
      await persist(records);
    } catch (err) {
      showError("删除失败，请重试。");
      return;
    }
    if (editingId === id) {
      resetForm();
    }
    renderAll();
  });
}

let dialogHandler = null;

function openDialog(title, text, confirmLabel, onConfirm) {
  els.dialogTitle.textContent = title;
  els.dialogText.textContent = text;
  els.dialogConfirm.textContent = confirmLabel;
  dialogHandler = onConfirm;
  els.dialog.hidden = false;
  if (typeof els.dialogConfirm.focus === "function") {
    els.dialogConfirm.focus();
  }
}

function closeDialog() {
  els.dialog.hidden = true;
  dialogHandler = null;
}

async function init() {
  const raw = await appStore.getState();
  const base = raw && typeof raw === "object" ? raw : {};
  const hasRecords = Array.isArray(base.records);
  state = Object.assign({}, base);
  state.records = hasRecords ? base.records.map(normalizeRecord) : [];

  if (!hasRecords) {
    try {
      await persist(state.records);
    } catch (err) {
      state = Object.assign({}, base, { records: [] });
    }
  }

  els.form.addEventListener("submit", handleSubmit);

  els.cancelEdit.addEventListener("click", function () {
    resetForm();
  });

  els.searchInput.addEventListener("input", function () {
    searchTerm = els.searchInput.value.trim().toLowerCase();
    renderSearch();
    renderList();
  });

  els.searchClear.addEventListener("click", function () {
    searchTerm = "";
    renderSearch();
    renderList();
    if (typeof els.searchInput.focus === "function") {
      els.searchInput.focus();
    }
  });

  els.filterButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      activeFilter = btn.getAttribute("data-filter") || "all";
      renderFilters();
      renderList();
    });
  });

  els.sortButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      sortOrder = normalizeSortOrder(btn.getAttribute("data-sort"));
      renderSort();
      renderList();
    });
  });

  els.dialogCancel.addEventListener("click", function () {
    closeDialog();
  });

  els.dialogConfirm.addEventListener("click", async function () {
    const handler = dialogHandler;
    closeDialog();
    if (typeof handler === "function") {
      await handler();
    }
  });

  els.dialog.addEventListener("click", function (event) {
    if (event.target === els.dialog) {
      closeDialog();
    }
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !els.dialog.hidden) {
      closeDialog();
    }
  });

  resetForm();
  renderAll();
}

await init();

artifact.css:
:root {
  --bg-900: #0a1220;
  --bg-800: #0f1b2d;
  --bg-700: #142338;
  --bg-600: #1b2f4a;
  --line: #24395a;
  --line-soft: #1d2f4b;
  --accent: #4c9bf5;
  --accent-strong: #2f7fe0;
  --accent-soft: rgba(76, 155, 245, 0.16);
  --text: #e8f1fb;
  --text-soft: #9db4cf;
  --text-dim: #7d93ae;
  --danger: #ff6b7a;
  --danger-soft: rgba(255, 107, 122, 0.14);
  --shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
  --radius: 14px;
}

#app {
  min-height: 100vh;
  background: radial-gradient(120% 90% at 50% 0%, #16273f 0%, var(--bg-900) 55%, #070d17 100%);
  color: var(--text);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-header {
  padding: 18px 18px 20px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, #1d3a63 0%, #14263f 100%);
  border: 1px solid var(--line);
  color: var(--text);
  box-shadow: var(--shadow);
}

.app-title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #ffffff;
}

.app-subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--text-soft);
}

.stats {
  background: var(--bg-800);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px;
  box-shadow: var(--shadow);
}

.stats-total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 4px 6px 12px;
  border-bottom: 1px dashed var(--line);
}

.stats-total-label {
  font-size: 14px;
  color: var(--text-soft);
}

.stats-total-value {
  font-size: 26px;
  font-weight: 700;
  color: var(--accent);
}

.stats-list {
  list-style: none;
  margin: 12px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.stat-item {
  background: var(--bg-700);
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.stat-name {
  font-size: 13px;
  color: var(--text-soft);
  display: flex;
  align-items: center;
  gap: 6px;
}

.stat-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--accent);
  flex: none;
}

.stat-dot[data-stage="pending"] { background: #8fa6c4; }
.stat-dot[data-stage="applied"] { background: var(--accent); }
.stat-dot[data-stage="interview"] { background: #f2b13c; }
.stat-dot[data-stage="closed"] { background: #6c7d92; }

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
}

.panel {
  background: var(--bg-800);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
}

.panel-title {
  margin: 0 0 12px;
  font-size: 16px;
  font-weight: 700;
  color: var(--text);
}

.record-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field-full {
  grid-column: 1 / -1;
}

.field-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-soft);
}

.field-input {
  width: 100%;
  padding: 10px 12px;
  font-size: 15px;
  font-family: inherit;
  color: var(--text);
  background: var(--bg-700);
  border: 1px solid var(--line);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
  appearance: none;
}

.field-input::placeholder {
  color: var(--text-dim);
}

.field-input:focus {
  background: var(--bg-600);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.field-textarea {
  resize: vertical;
  min-height: 72px;
}

select.field-input {
  background-image: linear-gradient(45deg, transparent 50%, var(--accent) 50%), linear-gradient(135deg, var(--accent) 50%, transparent 50%);
  background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

select.field-input option {
  background: var(--bg-700);
  color: var(--text);
}

input[type="date"].field-input::-webkit-calendar-picker-indicator {
  filter: invert(0.8);
  cursor: pointer;
}

.form-error {
  grid-column: 1 / -1;
  margin: 0;
  padding: 8px 12px;
  border-radius: 10px;
  background: var(--danger-soft);
  color: var(--danger);
  font-size: 13px;
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  padding: 10px 18px;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.1s ease, background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--accent-strong);
  color: #ffffff;
  flex: 1 1 160px;
}

.btn-primary:hover {
  background: var(--accent);
}

.btn-ghost {
  background: var(--bg-700);
  color: var(--text);
  border-color: var(--line);
}

.btn-ghost:hover {
  background: var(--bg-600);
  border-color: var(--accent);
}

.btn-danger {
  background: #d63a4c;
  color: #ffffff;
}

.btn-danger:hover {
  background: #e8495c;
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.list-count {
  font-size: 13px;
  color: var(--text-soft);
}

.search-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 4px 0 12px;
}

.search-label {
  display: block;
}

.search-box {
  display: flex;
  gap: 8px;
  align-items: stretch;
}

.search-input {
  flex: 1 1 auto;
  min-width: 0;
}

.search-clear {
  flex: none;
  font-size: 13px;
  padding: 8px 14px;
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 0 12px;
}

.sort-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 0 14px;
  padding: 8px 10px;
  border: 1px dashed var(--line);
  border-radius: 12px;
  background: var(--bg-700);
}

.sort-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-soft);
}

.sort-group {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.chip {
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  padding: 7px 14px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--bg-700);
  color: var(--text-soft);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.chip:hover {
  background: var(--bg-600);
  color: var(--text);
}

.chip.is-active {
  background: var(--accent-strong);
  border-color: var(--accent);
  color: #ffffff;
}

.sort-chip.is-active {
  background: var(--accent-soft);
  border-color: var(--accent);
  color: #a9d1fb;
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.record-card {
  border: 1px solid var(--line-soft);
  border-left: 4px solid var(--accent);
  border-radius: 12px;
  background: var(--bg-700);
  padding: 12px 14px;
}

.record-card[data-stage="pending"] { border-left-color: #8fa6c4; }
.record-card[data-stage="applied"] { border-left-color: var(--accent); }
.record-card[data-stage="interview"] { border-left-color: #f2b13c; }
.record-card[data-stage="closed"] { border-left-color: #6c7d92; }

.record-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--text);
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--text-soft);
  word-break: break-word;
}

.stage-badge {
  flex: none;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
  white-space: nowrap;
}

.stage-badge[data-stage="pending"] { background: rgba(143, 166, 196, 0.18); color: #b6c8dd; }
.stage-badge[data-stage="applied"] { background: rgba(76, 155, 245, 0.18); color: #7fbcfb; }
.stage-badge[data-stage="interview"] { background: rgba(242, 177, 60, 0.18); color: #f5c46b; }
.stage-badge[data-stage="closed"] { background: rgba(108, 125, 146, 0.2); color: #a6b4c4; }

.record-meta {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--text-soft);
}

.record-note {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--text);
  background: var(--bg-800);
  border: 1px dashed var(--line);
  border-radius: 10px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.record-actions .btn {
  font-size: 13px;
  padding: 7px 14px;
}

.empty-hint {
  margin: 8px 0 0;
  padding: 22px 12px;
  text-align: center;
  font-size: 14px;
  color: var(--text-soft);
  background: var(--bg-700);
  border: 1px dashed var(--line);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 9, 17, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 340px;
  background: var(--bg-800);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.6);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  color: var(--text);
}

.dialog-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--text-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

@media (max-width: 520px) {
  .app-shell {
    padding: 14px 12px 40px;
  }

  .record-form {
    grid-template-columns: minmax(0, 1fr);
  }

  .stats-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .app-title {
    font-size: 20px;
  }

  .sort-row {
    align-items: flex-start;
    flex-direction: column;
  }
}

artifact.js:
const STAGES = [
  { key: "pending", label: "待投递" },
  { key: "applied", label: "已投递" },
  { key: "interview", label: "面试中" },
  { key: "closed", label: "已结束" }
];
const STAGE_LABELS = STAGES.reduce(function (acc, s) { acc[s.key] = s.label; return acc; }, {});
const STAGE_KEYS = STAGES.map(function (s) { return s.key; });

const root = app;

const els = {
  statsList: root.querySelector("[data-stats-list]"),
  totalCount: root.querySelector("[data-total-count]"),
  form: root.querySelector("[data-record-form]"),
  formTitle: root.querySelector("[data-form-title]"),
  company: root.querySelector("#field-company"),
  position: root.querySelector("#field-position"),
  appliedAt: root.querySelector("#field-date"),
  stage: root.querySelector("#field-stage"),
  note: root.querySelector("#field-note"),
  formError: root.querySelector("[data-form-error]"),
  submitBtn: root.querySelector("[data-submit-btn]"),
  cancelEdit: root.querySelector("[data-cancel-edit]"),
  listCount: root.querySelector("[data-list-count]"),
  recordList: root.querySelector("[data-record-list]"),
  emptyHint: root.querySelector("[data-empty-hint]"),
  filterButtons: Array.prototype.slice.call(root.querySelectorAll("[data-filter]")),
  dialog: root.querySelector("[data-dialog]"),
  dialogTitle: root.querySelector("[data-dialog-title]"),
  dialogText: root.querySelector("[data-dialog-text]"),
  dialogCancel: root.querySelector("[data-dialog-cancel]"),
  dialogConfirm: root.querySelector("[data-dialog-confirm]")
};

let state = null;
let editingId = null;
let activeFilter = "all";

function normalizeStage(value) {
  return STAGE_KEYS.indexOf(value) >= 0 ? value : "pending";
}

function normalizeRecord(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const rec = Object.assign({}, src);
  rec.id = typeof src.id === "string" && src.id ? src.id : createId();
  rec.company = typeof src.company === "string" ? src.company : "";
  rec.position = typeof src.position === "string" ? src.position : "";
  rec.appliedAt = typeof src.appliedAt === "string" ? src.appliedAt : "";
  rec.stage = normalizeStage(src.stage);
  rec.note = typeof src.note === "string" ? src.note : "";
  return rec;
}

function createId() {
  return "rec-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
}

function getRecords() {
  return Array.isArray(state.records) ? state.records : [];
}

function todayISO() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return d.getFullYear() + "-" + m + "-" + day;
}

function formatDate(value) {
  if (!value) return "未填写日期";
  const parts = String(value).split("-");
  if (parts.length !== 3) return String(value);
  return parts[0] + " 年 " + Number(parts[1]) + " 月 " + Number(parts[2]) + " 日";
}

function showError(message) {
  if (!message) {
    els.formError.hidden = true;
    els.formError.textContent = "";
    return;
  }
  els.formError.textContent = message;
  els.formError.hidden = false;
}

function renderStats() {
  const records = getRecords();
  const counts = STAGE_KEYS.reduce(function (acc, key) { acc[key] = 0; return acc; }, {});
  records.forEach(function (rec) {
    const key = normalizeStage(rec.stage);
    counts[key] += 1;
  });

  els.statsList.textContent = "";
  STAGES.forEach(function (stage) {
    const li = document.createElement("li");
    li.className = "stat-item";

    const nameWrap = document.createElement("span");
    nameWrap.className = "stat-name";
    const dot = document.createElement("span");
    dot.className = "stat-dot";
    dot.setAttribute("data-stage", stage.key);
    const nameText = document.createElement("span");
    nameText.textContent = stage.label;
    nameWrap.appendChild(dot);
    nameWrap.appendChild(nameText);

    const value = document.createElement("span");
    value.className = "stat-value";
    value.textContent = String(counts[stage.key]);

    li.appendChild(nameWrap);
    li.appendChild(value);
    els.statsList.appendChild(li);
  });

  const total = STAGE_KEYS.reduce(function (sum, key) { return sum + counts[key]; }, 0);
  els.totalCount.textContent = String(total);
}

function renderFilters() {
  els.filterButtons.forEach(function (btn) {
    const key = btn.getAttribute("data-filter");
    if (key === activeFilter) {
      btn.classList.add("is-active");
    } else {
      btn.classList.remove("is-active");
    }
  });
}

function renderList() {
  const records = getRecords();
  const visible = activeFilter === "all"
    ? records
    : records.filter(function (rec) { return normalizeStage(rec.stage) === activeFilter; });

  els.recordList.textContent = "";

  visible.forEach(function (rec) {
    const li = document.createElement("li");
    li.className = "record-card";
    li.setAttribute("data-stage", normalizeStage(rec.stage));

    const top = document.createElement("div");
    top.className = "record-top";

    const titleWrap = document.createElement("div");
    const company = document.createElement("h3");
    company.className = "record-company";
    company.textContent = rec.company || "未填写公司";
    const position = document.createElement("p");
    position.className = "record-position";
    position.textContent = rec.position || "未填写岗位";
    titleWrap.appendChild(company);
    titleWrap.appendChild(position);

    const badge = document.createElement("span");
    badge.className = "stage-badge";
    badge.setAttribute("data-stage", normalizeStage(rec.stage));
    badge.textContent = STAGE_LABELS[normalizeStage(rec.stage)];

    top.appendChild(titleWrap);
    top.appendChild(badge);

    const meta = document.createElement("p");
    meta.className = "record-meta";
    meta.textContent = "投递日期：" + formatDate(rec.appliedAt);

    li.appendChild(top);
    li.appendChild(meta);

    if (rec.note) {
      const note = document.createElement("p");
      note.className = "record-note";
      note.textContent = rec.note;
      li.appendChild(note);
    }

    const actions = document.createElement("div");
    actions.className = "record-actions";

    const editBtn = document.createElement("button");
    editBtn.type = "button";
    editBtn.className = "btn btn-ghost";
    editBtn.textContent = "编辑";
    editBtn.addEventListener("click", function () {
      startEdit(rec.id);
    });

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "btn btn-ghost";
    delBtn.textContent = "删除";
    delBtn.addEventListener("click", function () {
      askDelete(rec.id);
    });

    actions.appendChild(editBtn);
    actions.appendChild(delBtn);
    li.appendChild(actions);

    els.recordList.appendChild(li);
  });

  const total = records.length;
  els.listCount.textContent = activeFilter === "all"
    ? "共 " + total + " 条"
    : "筛选 " + visible.length + " 条 / 共 " + total + " 条";

  if (visible.length === 0) {
    els.emptyHint.hidden = false;
    els.emptyHint.textContent = total === 0
      ? "还没有投递记录，先在上方新增一条吧。"
      : "当前阶段下没有记录，试试切换筛选条件。";
  } else {
    els.emptyHint.hidden = true;
    els.emptyHint.textContent = "";
  }
}

function renderAll() {
  renderStats();
  renderFilters();
  renderList();
}

function resetForm() {
  editingId = null;
  els.form.reset();
  els.appliedAt.value = todayISO();
  els.stage.value = "pending";
  els.formTitle.textContent = "新增投递记录";
  els.submitBtn.textContent = "保存记录";
  els.cancelEdit.hidden = true;
  showError("");
}

function startEdit(id) {
  const rec = getRecords().filter(function (r) { return r.id === id; })[0];
  if (!rec) return;
  editingId = id;
  els.company.value = rec.company || "";
  els.position.value = rec.position || "";
  els.appliedAt.value = rec.appliedAt || "";
  els.stage.value = normalizeStage(rec.stage);
  els.note.value = rec.note || "";
  els.formTitle.textContent = "编辑投递记录";
  els.submitBtn.textContent = "保存修改";
  els.cancelEdit.hidden = false;
  showError("");
  if (typeof els.company.focus === "function") {
    els.company.focus();
  }
}

async function persist(nextRecords) {
  const next = Object.assign({}, state);
  next.records = nextRecords;
  await appStore.setState(next);
  state = await appStore.getState();
  if (!Array.isArray(state.records)) {
    state = Object.assign({}, state, { records: [] });
  }
}

async function handleSubmit(event) {
  event.preventDefault();
  const company = els.company.value.trim();
  const position = els.position.value.trim();
  const appliedAt = els.appliedAt.value;
  const stage = normalizeStage(els.stage.value);
  const note = els.note.value.trim();

  if (!company) {
    showError("请填写公司名称。");
    return;
  }
  if (!position) {
    showError("请填写应聘岗位。");
    return;
  }
  showError("");

  const records = getRecords().slice();
  const targetId = editingId;

  if (targetId) {
    const index = records.findIndex(function (r) { return r.id === targetId; });
    if (index < 0) {
      showError("未找到要编辑的记录，请刷新后重试。");
      return;
    }
    records[index] = Object.assign({}, records[index], {
      company: company,
      position: position,
      appliedAt: appliedAt,
      stage: stage,
      note: note
    });
  } else {
    records.push({
      id: createId(),
      company: company,
      position: position,
      appliedAt: appliedAt,
      stage: stage,
      note: note
    });
  }

  try {
    await persist(records);
  } catch (err) {
    showError("保存失败，请重试。你的输入已保留。");
    return;
  }

  resetForm();
  renderAll();
}

function askDelete(id) {
  const rec = getRecords().filter(function (r) { return r.id === id; })[0];
  if (!rec) return;
  const label = (rec.company || "未填写公司") + " · " + (rec.position || "未填写岗位");
  openDialog("确认删除", "确定要删除「" + label + "」这条投递记录吗？删除后无法恢复。", "确认删除", async function () {
    const records = getRecords().filter(function (r) { return r.id !== id; });
    try {
      await persist(records);
    } catch (err) {
      showError("删除失败，请重试。");
      return;
    }
    if (editingId === id) {
      resetForm();
    }
    renderAll();
  });
}

let dialogHandler = null;

function openDialog(title, text, confirmLabel, onConfirm) {
  els.dialogTitle.textContent = title;
  els.dialogText.textContent = text;
  els.dialogConfirm.textContent = confirmLabel;
  dialogHandler = onConfirm;
  els.dialog.hidden = false;
  if (typeof els.dialogConfirm.focus === "function") {
    els.dialogConfirm.focus();
  }
}

function closeDialog() {
  els.dialog.hidden = true;
  dialogHandler = null;
}

async function init() {
  const raw = await appStore.getState();
  const base = raw && typeof raw === "object" ? raw : {};
  const hasRecords = Array.isArray(base.records);
  state = Object.assign({}, base);
  state.records = hasRecords ? base.records.map(normalizeRecord) : [];

  if (!hasRecords) {
    try {
      await persist(state.records);
    } catch (err) {
      state = Object.assign({}, base, { records: [] });
    }
  }

  els.form.addEventListener("submit", handleSubmit);

  els.cancelEdit.addEventListener("click", function () {
    resetForm();
  });

  els.filterButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      activeFilter = btn.getAttribute("data-filter") || "all";
      renderFilters();
      renderList();
    });
  });

  els.dialogCancel.addEventListener("click", function () {
    closeDialog();
  });

  els.dialogConfirm.addEventListener("click", async function () {
    const handler = dialogHandler;
    closeDialog();
    if (typeof handler === "function") {
      await handler();
    }
  });

  els.dialog.addEventListener("click", function (event) {
    if (event.target === els.dialog) {
      closeDialog();
    }
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !els.dialog.hidden) {
      closeDialog();
    }
  });

  resetForm();
  renderAll();
}

await init();

