:root {
  --blue-900: #0b2a4a;
  --blue-700: #14508c;
  --blue-600: #1a6fd4;
  --blue-500: #2b86e8;
  --blue-100: #e3eefb;
  --blue-050: #f2f7fe;
  --white: #ffffff;
  --ink: #12283f;
  --ink-soft: #4a6party;
  --ink-soft: #4a6b8a;
  --line: #d3e2f4;
  --danger: #c62f3d;
  --danger-soft: #fdecee;
  --shadow: 0 8px 24px rgba(16, 62, 116, 0.12);
  --radius: 14px;
}

#app {
  min-height: 100vh;
  background: linear-gradient(180deg, #eaf3fe 0%, #f7fbff 45%, #ffffff 100%);
  color: var(--ink);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-header {
  padding: 18px 18px 20px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--blue-700) 0%, var(--blue-500) 100%);
  color: var(--white);
  box-shadow: var(--shadow);
