  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-header {
  padding: 18px 18px 20px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--blue-700) 0%, var(--blue-500) 100%);
  color: var(--white);
  box-shadow: var(--shadow);
}

.app-title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.app-subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.86);
}

.stats {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px;
  box-shadow: var(--shadow);
}

.stats-total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 4px 6px 12px;
  border-bottom: 1px dashed var(--line);
}

.stats-total-label {
  font-size: 14px;
  color: var(--ink-soft);
}

.stats-total-value {
  font-size: 26px;
  font-weight: 700;
  color: var(--blue-700);
}

.stats-list {
  list-style: none;
  margin: 12px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.stat-item {
  background: var(--blue-050);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.stat-name {
  font-size: 13px;
  color: var(--ink-soft);
  display: flex;
  align-items: center;
  gap: 6px;
}

.stat-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--blue-500);
  flex: none;
}

.stat-dot[data-stage="pending"] { background: #7f9dc0; }
.stat-dot[data-stage="applied"] { background: var(--blue-600); }
.stat-dot[data-stage="interview"] { background: #f0a02a; }
.stat-dot[data-stage="closed"] { background: #8a97a6; }

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--blue-900);
}

.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
}

.panel-title {
  margin: 0 0 12px;
  font-size: 16px;
  font-weight: 700;
  color: var(--blue-900);
}

.record-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field-full {
  grid-column: 1 / -1;
}

.field-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--blue-700);
}

.field-input {
  width: 100%;
  padding: 10px 12px;
  font-size: 15px;
  font-family: inherit;
  color: var(--ink);
  background: var(--blue-050);
  border: 1px solid var(--line);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
  appearance: none;
}

.field-input::placeholder {
  color: #93a9c2;
}

.field-input:focus {
  background: var(--white);
  border-color: var(--blue-500);
  box-shadow: 0 0 0 3px rgba(43, 134, 232, 0.18);
}

.field-textarea {
  resize: vertical;
  min-height: 72px;
}

select.field-input {
  background-image: linear-gradient(45deg, transparent 50%, var(--blue-700) 50%), linear-gradient(135deg, var(--blue-700) 50%, transparent 50%);
  background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

.form-error {
  grid-column: 1 / -1;
  margin: 0;
  padding: 8px 12px;
  border-radius: 10px;
  background: var(--danger-soft);
  color: var(--danger);
  font-size: 13px;
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  padding: 10px 18px;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.1s ease, background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--blue-600);
  color: var(--white);
  flex: 1 1 160px;
}

.btn-primary:hover {
  background: var(--blue-700);
}

.btn-ghost {
  background: var(--white);
  color: var(--blue-700);
  border-color: var(--line);
}

.btn-ghost:hover {
  background: var(--blue-100);
}

.btn-danger {
  background: var(--danger);
  color: var(--white);
}

.btn-danger:hover {
  background: #a8232f;
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.list-count {
  font-size: 13px;
  color: var(--ink-soft);
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 4px 0 14px;
}

.chip {
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  padding: 7px 14px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--blue-050);
  color: var(--blue-700);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.chip:hover {
  background: var(--blue-100);
}

.chip.is-active {
  background: var(--blue-600);
  border-color: var(--blue-600);
  color: var(--white);
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.record-card {
  border: 1px solid var(--line);
  border-left: 4px solid var(--blue-500);
  border-radius: 12px;
  background: var(--blue-050);
  padding: 12px 14px;
}

.record-card[data-stage="pending"] { border-left-color: #7f9dc0; }
.record-card[data-stage="applied"] { border-left-color: var(--blue-600); }
.record-card[data-stage="interview"] { border-left-color: #f0a02a; }
.record-card[data-stage="closed"] { border-left-color: #8a97a6; }

.record-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--blue-900);
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
  word-break: break-word;
}

.stage-badge {
  flex: none;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--blue-100);
  color: var(--blue-700);
  white-space: nowrap;
}

.stage-badge[data-stage="pending"] { background: #e6ecf4; color: #4a6b8a; }
.stage-badge[data-stage="applied"] { background: #dbeafe; color: #14508c; }
.stage-badge[data-stage="interview"] { background: #fdf0d8; color: #9a6207; }
.stage-badge[data-stage="closed"] { background: #e8ebef; color: #5c6b7a; }

.record-meta {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.record-note {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--ink);
  background: var(--white);
  border: 1px dashed var(--line);
  border-radius: 10px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.record-actions .btn {
  font-size: 13px;
  padding: 7px 14px;
}

.empty-hint {
  margin: 8px 0 0;
  padding: 22px 12px;
  text-align: center;
  font-size: 14px;
  color: var(--ink-soft);
  background: var(--blue-050);
  border: 1px dashed var(--line);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(11, 42, 74, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 340px;
  background: var(--white);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: 0 18px 40px rgba(11, 42, 74, 0.28);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  color: var(--blue-900);
}

.dialog-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--ink-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

@media (max-width: 520px) {
  .app-shell {
    padding: 14px 12px 40px;
  }

  .record-form {
    grid-template-columns: minmax(0, 1fr);
  }

  .stats-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .app-title {
    font-size: 20px;
  }
}
